import json
import sqlite3

VALID_CABINS = {'business', 'economy', 'basic_economy'}
VALID_STATUSES = {'available', 'on time', 'delayed', 'flying', 'landed', 'cancelled'}

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row

rows = conn.execute("SELECT flight_id, dates_json FROM flights WHERE source_skill='tau2Airline'").fetchall()
count = 0
for r in rows:
    dates = json.loads(r['dates_json'] or '{}')
    changed = False
    for dk, dv in dates.items():
        # Fix invalid statuses
        if dv.get('status') not in VALID_STATUSES:
            dv['status'] = 'available'
            # Ensure it has required fields for available
            if 'available_seats' not in dv:
                dv['available_seats'] = {'economy': 50, 'business': 10, 'basic_economy': 30}
            if 'prices' not in dv:
                dv['prices'] = {'economy': 100, 'business': 300, 'basic_economy': 80}
            changed = True
        # Strip invalid cabin keys from prices and available_seats
        for field in ('prices', 'available_seats'):
            if field in dv:
                bad_keys = [k for k in dv[field] if k not in VALID_CABINS]
                for k in bad_keys:
                    del dv[field][k]
                    changed = True
    if changed:
        conn.execute("UPDATE flights SET dates_json=? WHERE flight_id=?", (json.dumps(dates), r['flight_id']))
        count += 1

# Also fix NULL times
conn.execute("UPDATE flights SET departure_time=COALESCE(departure_time,'00:00:00'), arrival_time=COALESCE(arrival_time,'00:00:00') WHERE source_skill='tau2Airline'")

conn.commit()
conn.close()
print(f"Fixed {count} flights total")
PYEOF

